import {useOrderPage} from '../hooks/useOrderPage'
import {orderStates,time} from '../shared/types'
const Detail=defineAsyncComponent(()=>import('../shared/components/QualityDetail.vue'))
const props=defineProps<{level:number}>(),vm=reactive(useOrderPage(props.level))
</script>
<template><a-card :title="(level===1?qt('company'):qt('project2'))+qt('inspectionRecords')"><template #extra><a-space><a-button :loading="vm.loading" @click="vm.load">{{qt('refresh')}}</a-button><a-button v-if="vm.can('quality-work-order','export')" @click="vm.exportRows">{{qt('export')}}</a-button></a-space></template><a-alert v-if="vm.error" :message="vm.error" type="error" show-icon />
 <a-space wrap style="margin-bottom:16px"><a-select v-model:value="vm.projectId" show-search option-filter-prop="label" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" :placeholder="qt('allBusinessProjects')" allow-clear style="width:240px" /><a-select v-model:value="vm.status" :options="Object.entries(orderStates).map(([value,label])=>({value:Number(value),label}))" :placeholder="qt('allStatuses')" allow-clear style="width:150px" /></a-space><ConditionFilter v-model="vm.terms" :fields="vm.fields" @change="vm.search" />
 <a-tabs v-model:activeKey="vm.mode"><a-tab-pane key="pool" :tab="qt('allWorkOrders')" /><a-tab-pane key="inspect" :tab="qt('myPendingInspections')" /><a-tab-pane key="rectify" :tab="qt('myPendingRectifications')" /><a-tab-pane key="review" :tab="qt('myPendingReviews')" /><a-tab-pane key="completed" :tab="qt('myCompletedOrders')" /><a-tab-pane key="related" :tab="qt('participationHistory')" /></a-tabs>
 <a-table :data-source="vm.rows" :loading="vm.loading" row-key="id" :scroll="{x:'max-content'}" :pagination="{current:vm.current,total:vm.total,pageSize:20,showSizeChanger:false}" @change="(p:{current?:number})=>{vm.current=p.current||1;vm.load()}"><a-table-column :title="qt('taskName')" key="name"><template #default="{record}"><a-button type="link" @click="vm.detail(record)">{{record.taskName}}</a-button></template></a-table-column><a-table-column :title="qt('businessProject')" data-index="projectName" /><a-table-column :title="qt('orderNumber')" data-index="taskCode" /><a-table-column :title="qt('status')" key="status"><template #default="{record}"><a-tag :color="record.workOrderStatus===4?'green':'blue'">{{orderStates[record.workOrderStatus]}}</a-tag></template></a-table-column><a-table-column :title="qt('generationTime')" key="time"><template #default="{record}">{{time(record.scheduledTime)}}</template></a-table-column><a-table-column :title="qt('submissionTimeLimit')" key="deadline"><template #default="{record}">{{time(record.reportDeadline)}}</template></a-table-column><a-table-column :title="qt('totalScore')" data-index="totalScore" /><a-table-column :title="qt('rating')" data-index="evaluationName" /><a-table-column :title="qt('actions')" key="actions"><template #default="{record}"><a-button type="link" @click="vm.detail(record)">{{qt('viewProcess')}}</a-button></template></a-table-column></a-table>
